+fn materialize_builder_paint(paint: &mut PaintValue) -> &mut Paint {
+    if !matches!(paint, PaintValue::Styled(_)) {
+        *paint = PaintValue::Styled(std::boxed::Box::new(paint.resolve()));
+    }
+    let PaintValue::Styled(paint) = paint else {
+        unreachable!()
+    };
+    paint
+}
+
+impl Stylable for Box {
+    fn style_parts(&mut self) -> (&mut LayoutStyle, &mut Paint, &mut TypoChain) {
+        (
+            &mut self.style,
+            materialize_builder_paint(&mut self.paint),
+            &mut self.typo,
+        )
+    }
+
+    fn layout_mut(&mut self) -> &mut LayoutStyle {
+        &mut self.style
+    }
+
+    fn paint_mut(&mut self) -> &mut Paint {
+        materialize_builder_paint(&mut self.paint)
+    }
+
+    fn set_builder_fill(&mut self, fill: Oklch) {
+        match &mut self.paint {
+            PaintValue::Styled(paint) => paint.fill = Some(fill),
+            _ if fill == fill => self.paint = PaintValue::Solid(fill),
+            _ => {
+                self.paint = Paint {
+                    fill: Some(fill),
+                    ..Paint::default()
+                }
+                .into();
+            }
+        }
+    }
+
+    fn set_builder_paint(&mut self, paint: Paint) {
+        self.paint = paint.into();
+    }
+
+    fn apply_style(&mut self, style: &Style) {
+        match &mut self.paint {
+            PaintValue::Styled(paint) => style.apply_to(&mut self.style, paint),
+            _ => {
+                let mut paint = std::mem::take(&mut self.paint).into();
+                style.apply_to(&mut self.style, &mut paint);
+                self.paint = paint.into();
+            }
+        }
+        apply_typography(style, &mut self.typo);
+        self.post_style(style);
+    }
+}
